// Dailies: play the film headless and grab frames at key story beats.
import { chromium } from 'playwright';
import { mkdirSync } from 'fs';

mkdirSync('dailies', { recursive: true });

const browser = await chromium.launch({ channel: 'msedge', headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });

const errors = [];
page.on('pageerror', e => errors.push('PAGE ERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });

await page.goto('http://localhost:8741/index.html', { waitUntil: 'networkidle' });
await page.waitForTimeout(1500);
await page.screenshot({ path: 'dailies/00_menu.png' });

await page.click('#playBtn');

// beats: [filmTime, label]
const beats = [
  [3, 'shot1_establishing'], [9, 'shot2_mouse_insert'], [13.5, 'shot3_cat_alert'],
  [20, 'shot4_tracking'], [27, 'shot5_under_bed'], [32, 'shot6_window_light'],
  [38.5, 'shot7_blocks'], [45, 'shot8_crane'], [52, 'shot9_winddown'], [57.5, 'shot10_fin'],
];

const t0 = Date.now();
for (const [t, label] of beats) {
  const wait = t * 1000 - (Date.now() - t0);
  if (wait > 0) await page.waitForTimeout(wait);
  await page.screenshot({ path: `dailies/${String(t).padStart(4, '0')}_${label}.png` });
  console.log('captured', label);
}

console.log(errors.length ? errors.join('\n') : 'NO JS ERRORS');
await browser.close();
